import type { MetadataRoute } from "next";

import { queryPublishedPlatforms } from "@/lib/data/registry";
import { recentlyVerdictedTokens } from "@/lib/data/ledger";
import { buildScanSlug } from "@/lib/scan-slug";
import { SITE_URL } from "@/lib/config/site";

/**
 * /sitemap.xml — generated by Next's App Router metadata convention.
 *
 * Top-level routes, plus **every published /ecosystem/<slug>**.
 *
 * …plus the **500 most recently scanned tokens**, as canonical `/scan/<ticker>-<addr>`
 * URLs. These used to be excluded with the rest of the per-token pages, and the
 * reason was sound at the time: the page rendered an empty client-side form, so
 * every one of those URLs would have advertised a page with nothing on it. The
 * verdict is now server-rendered, which is what earns them the entry. Two
 * conditions still hold them honest — the **cap**, because the set is otherwise
 * unbounded and a sitemap a crawler times out on advertises nothing, and the
 * **one-row-per-token** shape, because `?v=` receipts are noindex and must never
 * appear here.
 *
 * /rwa/[address] and /wanted/[deployer] stay out on the original reasoning.
 *
 * The ecosystem listings are the opposite case — a small, curated, statically
 * rendered set whose whole purpose is to be indexed, so leaving them out of the
 * sitemap was leaving the only genuinely rankable pages on the site
 * undiscoverable.
 *
 * The listing read degrades to `[]` with no database (§1), so a build without
 * `DATABASE_URL` emits the static routes rather than failing.
 */

/**
 * **force-dynamic, and this one is not the usual mistake.**
 *
 * `Dockerfile.prod` builds with no `DATABASE_URL` (lib/config/isr-paths.ts), so
 * a statically-generated sitemap would bake `platforms = []` into the image and
 * serve a listing-free sitemap.xml until something invalidated it — the exact
 * empty-snapshot bug that file exists to document, on the one route whose whole
 * job is telling crawlers what exists.
 *
 * §5 rejects `force-dynamic` for pages because it means full SSR on every
 * request, forever. That objection does not apply here: sitemap.xml is fetched
 * by crawlers a handful of times a day, and the read behind it is one cached
 * query (queryPublishedPlatforms has its own 5-minute TTL).
 */
export const dynamic = "force-dynamic";

/** [path, changeFrequency, priority] for each canonical public route. */
const ROUTES: Array<[string, MetadataRoute.Sitemap[number]["changeFrequency"], number]> = [
  ["/", "daily", 1.0],
  ["/rwa", "daily", 0.95],
  ["/scan", "daily", 0.9],
  ["/night-market", "hourly", 0.9],
  ["/swap", "daily", 0.9],
  ["/ecosystem", "daily", 0.9],
  ["/robin-knight", "daily", 0.85],
  ["/ledger", "daily", 0.8],
  ["/wanted", "daily", 0.8],
  ["/token-sale", "weekly", 0.7],
  ["/overview", "weekly", 0.7],
  ["/compare", "weekly", 0.6],
  ["/methodology", "monthly", 0.5],
  ["/story", "monthly", 0.4],
];

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const lastModified = new Date();
  const base: MetadataRoute.Sitemap = ROUTES.map(([path, changeFrequency, priority]) => ({
    url: `${SITE_URL}${path}`,
    lastModified,
    changeFrequency,
    priority,
  }));

  // A token with a receipt is a page with content; one without renders the scan
  // form and is noindex, so it is never in this list by construction — the query
  // reads the ledger, and a row in the ledger IS the published verdict.
  const tokens = await recentlyVerdictedTokens(500);
  const scans: MetadataRoute.Sitemap = tokens.map((t) => ({
    url: `${SITE_URL}/scan/${buildScanSlug(t.token_address, t.token_symbol)}`,
    lastModified: new Date(t.created_at),
    changeFrequency: "weekly" as const,
    priority: 0.6,
  }));

  const platforms = await queryPublishedPlatforms();
  const listings: MetadataRoute.Sitemap = platforms.map((p) => ({
    url: `${SITE_URL}/ecosystem/${p.slug}`,
    // A listing changes when an admin edits it, or when its pools/tokens update.
    lastModified: p.created_at ? new Date(p.created_at) : lastModified,
    changeFrequency: "weekly" as const,
    // Ecosystem partner pages are prime entity targets for organic long-tail search.
    priority: 0.8,
  }));

  return [...base, ...listings, ...scans];
}
